package au.aumanet.app;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.*;
/** Bounded SOCKS5 endpoint + TCP/UDP forwarding. The maintained TUN engine owns IP/TCP.
 * This adapter only frames already-authenticated TCP streams and UDP datagrams. */
final class InternetTunnel{
 interface Access{boolean live();boolean charge(int bytes);Socket internet(InternetWire.Address target)throws Exception;DatagramSocket datagram()throws Exception;InetAddress resolve(InternetWire.Address target)throws Exception;Socket upstream(int kind,InternetWire.Address target)throws Exception;}
 private static final AtomicBoolean cleanupFault=new AtomicBoolean();
 private static final ThreadFactory closerFactory=work->{Thread t=new Thread(null,work,"AuMaNET-internet-close",128*1024);t.setDaemon(true);return t;};
 private static final ThreadPoolExecutor closers=new ThreadPoolExecutor(2,2,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(64),closerFactory);
 private static final ScheduledExecutorService closeWatch=Executors.newSingleThreadScheduledExecutor(closerFactory);
 static final class Resources implements Closeable{final AtomicBoolean retiring=new AtomicBoolean(),physicalDone=new AtomicBoolean();static boolean availableForNew(){return !cleanupFault.get();}
 /** Fast permission fence; descriptor cleanup never blocks the group/privacy caller. */
 void retire(){active.set(false);if(!retiring.compareAndSet(false,true))return;closeWatch.schedule(()->{if(!physicalDone.get())cleanupFault.set(true);},5,TimeUnit.SECONDS);submitClose();}
 private void submitClose(){try{closers.execute(this::close);}catch(RejectedExecutionException full){cleanupFault.set(true);closeWatch.schedule(this::submitClose,1,TimeUnit.SECONDS);}}
final AtomicBoolean active=new AtomicBoolean(true);final Set<Closeable> entries=ConcurrentHashMap.newKeySet();<T extends Closeable>T own(T c)throws IOException{if(!active.get()){c.close();throw new IOException("Internet session stopped");}entries.add(c);if(!active.get()){c.close();throw new IOException("Internet session stopped");}return c;}void forget(Closeable c){entries.remove(c);}public void close(){active.set(false);for(Closeable c:entries)try{c.close();entries.remove(c);}catch(Exception ignored){cleanupFault.set(true);}physicalDone.set(entries.isEmpty());}}
 static Thread thread(String name,Runnable action){Thread t=new Thread(null,action,name,128*1024);t.setDaemon(true);t.setPriority(Thread.MIN_PRIORITY);t.start();return t;}
 static boolean valid(Access a,Resources r){return r.active.get()&&a.live();}
 static void close(Socket... sockets){for(Socket socket:sockets)try{socket.close();}catch(Exception ignored){}}
 static boolean plainToFrames(Socket plain,Socket secure,Access a,Resources r){try{InputStream input=plain.getInputStream();DataOutputStream output=new DataOutputStream(secure.getOutputStream());byte[] buffer=new byte[4096];long last=System.nanoTime();while(valid(a,r)){int n;try{n=input.read(buffer);}catch(SocketTimeoutException check){if(System.nanoTime()-last>120000000000L)return false;continue;}if(n<0){output.writeInt(0);output.flush();return true;}if(n==0)continue;last=System.nanoTime();if(!valid(a,r)||!a.charge(n))return false;output.writeInt(n);output.write(buffer,0,n);output.flush();}}catch(Exception ignored){}return false;}
 static boolean framesToPlain(Socket secure,Socket plain,Access a,Resources r){try{DataInputStream input=new DataInputStream(secure.getInputStream());OutputStream output=plain.getOutputStream();InternetWire.StreamReader reader=new InternetWire.StreamReader();long last=System.nanoTime();while(valid(a,r)){byte[] frame;try{frame=reader.read(input);}catch(SocketTimeoutException check){if(System.nanoTime()-last>120000000000L)return false;continue;}last=System.nanoTime();if(frame.length==0){plain.shutdownOutput();return true;}if(!valid(a,r)||!a.charge(frame.length))return false;output.write(frame);output.flush();}}catch(Exception ignored){}return false;}
 static void tcp(Socket plain,Socket secure,Access a,Resources r)throws Exception{r.own(plain);r.own(secure);plain.setSoTimeout(1000);secure.setSoTimeout(1000);Thread returning=thread("AuMaNET-internet-return",()->{if(!framesToPlain(secure,plain,a,r))close(plain,secure);});try{if(!plainToFrames(plain,secure,a,r))close(plain,secure);try{returning.join(120000);}catch(InterruptedException stop){Thread.currentThread().interrupt();}}finally{close(plain,secure);r.forget(plain);r.forget(secure);}}
 static void donor(Socket secure,int kind,Access access,Resources resources)throws Exception{DataInputStream in=new DataInputStream(secure.getInputStream());DataOutputStream out=new DataOutputStream(secure.getOutputStream());if(kind==InternetWire.PING){out.writeByte(access.live()?0:1);out.flush();return;}if(kind==InternetWire.TCP){InternetWire.Address target=InternetWire.readAddress(in);Socket remote=access.internet(target);out.writeByte(0);out.flush();tcp(remote,secure,access,resources);return;}DatagramSocket udp=resources.own(access.datagram());udp.setSoTimeout(1000);out.writeByte(0);out.flush();Set<String> endpoints=ConcurrentHashMap.newKeySet();Thread returned=thread("AuMaNET-internet-udp-return",()->{try{byte[] buffer=new byte[InternetWire.MAX_UDP];while(valid(access,resources)&&!secure.isClosed()){DatagramPacket p=new DatagramPacket(buffer,buffer.length);try{udp.receive(p);}catch(SocketTimeoutException timeout){continue;}InternetWire.Address from=InternetWire.actual(p.getAddress(),p.getPort());if(!endpoints.contains(from.key())||!valid(access,resources)||!access.charge(p.getLength()))continue;InternetWire.datagram(out,from,p.getData(),p.getLength());}}catch(Exception ignored){}finally{try{secure.close();}catch(Exception ignored){}}});
  InternetWire.DatagramReader requests=new InternetWire.DatagramReader();try{secure.setSoTimeout(1000);while(valid(access,resources)){InternetWire.Datagram p;try{p=requests.read(in);}catch(SocketTimeoutException timeout){continue;}InetAddress ip=access.resolve(p.address);InternetWire.Address actual=InternetWire.actual(ip,p.address.port);if(endpoints.size()>=16&&!endpoints.contains(actual.key()))throw new IOException("UDP destination limit");endpoints.add(actual.key());if(!valid(access,resources)||!access.charge(p.payload.length))break;udp.send(new DatagramPacket(p.payload,p.payload.length,ip,p.address.port));}}finally{udp.close();resources.forget(udp);secure.close();returned.interrupt();}
 }
 static void socks(Socket local,String user,String password,Access access,Resources resources)throws Exception{resources.own(local);local.setSoTimeout(15000);DataInputStream in=new DataInputStream(local.getInputStream());DataOutputStream out=new DataOutputStream(local.getOutputStream());if(in.readUnsignedByte()!=5)throw new IOException("SOCKS version");int methods=in.readUnsignedByte();boolean auth=false;for(int i=0;i<methods;i++)if(in.readUnsignedByte()==2)auth=true;out.write(new byte[]{5,(byte)(auth?2:255)});out.flush();if(!auth)return;if(in.readUnsignedByte()!=1)throw new IOException("SOCKS authentication");int n=in.readUnsignedByte();byte[] u=new byte[n];in.readFully(u);n=in.readUnsignedByte();byte[] credential=new byte[n];in.readFully(credential);boolean accepted=java.security.MessageDigest.isEqual(u,user.getBytes(java.nio.charset.StandardCharsets.US_ASCII))&&java.security.MessageDigest.isEqual(credential,password.getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.write(new byte[]{1,(byte)(accepted?0:1)});out.flush();if(!accepted||!valid(access,resources))return;if(in.readUnsignedByte()!=5)throw new IOException("SOCKS version");int command=in.readUnsignedByte();if(in.readUnsignedByte()!=0)throw new IOException("SOCKS reserved");InternetWire.Address address=InternetWire.readAddress(in);if(!valid(access,resources))return;
  if(command==1){Socket upstream=access.upstream(InternetWire.TCP,address);out.write(new byte[]{5,0,0,1,0,0,0,0,0,0});out.flush();tcp(local,upstream,access,resources);return;}
  if(command!=3){out.write(new byte[]{5,7,0,1,0,0,0,0,0,0});out.flush();return;}Socket secure=resources.own(access.upstream(InternetWire.UDP,null));secure.setSoTimeout(1000);DatagramSocket udp=resources.own(new DatagramSocket(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0)));udp.setSoTimeout(1000);DataInputStream fromDonor=new DataInputStream(secure.getInputStream());DataOutputStream toDonor=new DataOutputStream(secure.getOutputStream());out.write(new byte[]{5,0,0,1,127,0,0,1});out.writeShort(udp.getLocalPort());out.flush();AtomicReference<SocketAddress> destination=new AtomicReference<>();
  Thread control=thread("AuMaNET-socks-udp-control",()->{try{local.setSoTimeout(1000);while(valid(access,resources))try{if(in.read()<0)break;}catch(SocketTimeoutException timeout){}}catch(Exception ignored){}finally{try{secure.close();}catch(Exception ignored){}udp.close();}});
  InternetWire.DatagramReader responses=new InternetWire.DatagramReader();Thread receiver=thread("AuMaNET-socks-udp-return",()->{try{while(valid(access,resources)){InternetWire.Datagram p;try{p=responses.read(fromDonor);}catch(SocketTimeoutException timeout){continue;}SocketAddress target=destination.get();if(target==null)continue;ByteArrayOutputStream encoded=new ByteArrayOutputStream(p.payload.length+260);DataOutputStream d=new DataOutputStream(encoded);d.write(new byte[]{0,0,0});InternetWire.writeAddress(d,p.address);d.write(p.payload);byte[] bytes=encoded.toByteArray();if(!valid(access,resources)||!access.charge(p.payload.length))break;udp.send(new DatagramPacket(bytes,bytes.length,target));}}catch(Exception ignored){}finally{udp.close();}});
  try{byte[] buffer=new byte[InternetWire.MAX_UDP+260];while(valid(access,resources)&&!secure.isClosed()){DatagramPacket packet=new DatagramPacket(buffer,buffer.length);try{udp.receive(packet);}catch(SocketTimeoutException timeout){continue;}if(!packet.getAddress().isLoopbackAddress())continue;SocketAddress peer=packet.getSocketAddress();if(destination.get()==null)destination.compareAndSet(null,peer);if(!peer.equals(destination.get()))continue;ByteArrayInputStream bytes=new ByteArrayInputStream(packet.getData(),0,packet.getLength());DataInputStream body=new DataInputStream(bytes);if(body.readUnsignedShort()!=0||body.readUnsignedByte()!=0)continue;InternetWire.Address target=InternetWire.readAddress(body);byte[] payload=new byte[bytes.available()];body.readFully(payload);if(!valid(access,resources)||!access.charge(payload.length))break;InternetWire.datagram(toDonor,target,payload,payload.length);}}finally{udp.close();local.close();secure.close();control.interrupt();receiver.interrupt();resources.forget(local);resources.forget(secure);resources.forget(udp);}
 }
 private InternetTunnel(){}
}

